<template><section v-if="verified" aria-label="排班固定优化与证明核对"><p>排班范围为所选科室和审核后的容量情景。请核对各时段人员安排。</p><p class="hash">原计划 {{ source.source_id }}<br />原可用截止 {{ source.as_of }} · 当前捕获 {{ source.captured_at }}<br />{{ source.business_dates[0] }} 至 {{ source.business_dates.at(-1) }} · {{ source.business_timezone }}</p><p>完整人员 {{ source.staff.length }}；会话 {{ source.sessions.length }}；完整配对 {{ source.options.length }}。{{ source.objective_mode==='meet_targets_min_penalty'?'满足硬需求后最小化明确惩罚':'先最大化计划净服务量，再最小化明确惩罚' }}。</p><el-button @click="emit('inspect',source.source_id)">核对完整受审排班原件</el-button>
 <template v-if="analysis"><el-alert :title="solveLabels[analysis.solve_status]" :type="analysis.solve_status==='optimal_proven'?'success':'info'" :closable="false" /><p>已证明最优 {{ analysis.optimality_proven }}；已证明不可行 {{ analysis.infeasibility_proven }}。</p><p>已知可行候选目标：{{ objective(analysis.feasible_incumbent_objective) }}<br />显式放宽资料的数学界：{{ objective(analysis.optimistic_objective_bound) }}。</p><p>计划服务量间隙：{{ source.objective_mode==='meet_targets_min_penalty'?'此目标不按服务量排序':quantity(analysis.planned_slots_gap) }}；服务量界闭合后的惩罚间隙：{{ quantity(analysis.penalty_gap_when_slot_bound_closed) }}。{{ analysis.planned_slots_gap>0?'服务量界尚未闭合，不能用惩罚差宣称最优。':'' }}</p>
 <template v-if="analysis.solution?.status==='feasible_under_declared_scope'"><h4>明确声明范围内的可行候选</h4><p>计划净服务量 {{ quantity(analysis.solution.total_planned_slots) }}；原惩罚点 {{ quantity(analysis.solution.cost_points) }}。</p><el-table :data="allocations" aria-label="排班候选逐会话场景容量"><el-table-column label="原日期会话" min-width="280"><template #default="{row}">{{ sessionLabel(row.session_id) }}</template></el-table-column><el-table-column label="整班分配人数"><template #default="{row}">{{ quantity(row.assigned_staff) }}</template></el-table-column><el-table-column v-for="[key,label] in [['staff_slot_capacity','人员场景能力'],['required_slots','硬需求'],['facility_slot_ceiling','设施净容量上限'],['planned_slots','候选计划量'],['capacity_headroom','场景余裕']]" :key="key" :label="label"><template #default="{row}">{{ quantity(row[key]) }}</template></el-table-column></el-table><el-pagination v-if="analysis.solution.session_allocations.length>20" v-model:current-page="allocationPage" :total="analysis.solution.session_allocations.length" :page-size="20" layout="prev,pager,next" /><details><summary>核对全部候选人员与会话分配</summary><p v-for="id in selectedOptions" :key="id">{{ optionLabel(id) }}</p><el-pagination v-if="analysis.solution.selected_option_ids.length>20" v-model:current-page="optionPage" :total="analysis.solution.selected_option_ids.length" :page-size="20" layout="prev,pager,next" /></details></template><p v-else>当前未展示已被固定程序确认为可行的实际候选；未知资料或放宽域搜索结果不会代作可行排班。</p>
 <el-table :data="[analysis.definite_search,analysis.optimistic_search]" aria-label="排班两图固定搜索证明"><el-table-column label="搜索域"><template #default="{row}">{{ row.graph==='definite'?'确定可行域':'显式放宽域' }}</template></el-table-column><el-table-column prop="expanded_nodes" label="实际展开节点" /><el-table-column prop="primitive_operations" label="实际原语操作" /><el-table-column prop="frontier_nodes" label="剩余前沿节点" /><el-table-column label="终止依据"><template #default="{row}">{{ termination[row.termination] }}</template></el-table-column><el-table-column label="数学目标与界"><template #default="{row}">{{ objective(row.incumbent_objective) }}；界 {{ objective(row.optimistic_bound) }}</template></el-table-column></el-table><p v-if="analysis.optimistic_search.relaxations.length">显式放宽项：{{ analysis.optimistic_search.relaxations.join('；') }}。</p>
 <p v-for="text in noticeList(analysis.warnings)" :key="text">{{ text }}</p><p v-for="text in noticeList(analysis.missing_data)" :key="text">待核实：{{ text }}</p><el-collapse><el-collapse-item title="逐项约束与原时间窗口核对"><el-select v-model="filter" aria-label="排班约束核对状态"><el-option label="全部已知及未知核对" value="all" /><el-option v-for="(label,key) in checkLabels" :key="key" :value="key" :label="label" /></el-select><el-table :data="checkRows" aria-label="排班候选逐项约束证据"><el-table-column label="原约束与状态" min-width="220"><template #default="{row}">{{ kindLabels[row.kind] }} · {{ checkLabels[row.status] }}<br />{{ row.reason_codes.join('；') }}</template></el-table-column><el-table-column label="人员与会话" min-width="240"><template #default="{row}">{{ staffLabel(row.staff_id) }}<br />{{ row.session_id?sessionLabel(row.session_id):'' }}</template></el-table-column><el-table-column label="原UTC窗口" min-width="250"><template #default="{row}">{{ row.witness_start_at??'无原窗口' }}<br />{{ row.witness_end_at??'无原窗口' }}</template></el-table-column><el-table-column label="实际与上限原量" min-width="240"><template #default="{row}">实际微秒 {{ quantity(row.actual_microseconds) }}；上限微秒 {{ quantity(row.limit_microseconds) }}<br />实际计数 {{ quantity(row.actual_count) }}；上限计数 {{ quantity(row.limit_count) }}<br />已核窗口 {{ quantity(row.evaluated_window_count) }}</template></el-table-column></el-table><el-pagination v-if="checks.length>20" v-model:current-page="checkPage" :total="checks.length" :page-size="20" layout="prev,pager,next" /><p>人工候选核对 {{ analysis.submitted_candidate_check?checkLabels[analysis.submitted_candidate_check.status]||analysis.submitted_candidate_check.status:'未提交（null）' }}；人工候选与优化程序找到的候选分别保留。</p></el-collapse-item></el-collapse><p class="hash">固定运行 {{ analysis.local_runtime.model_version }}；时区库 {{ analysis.local_runtime.timezone_database_digest }}。Prompt只作溯源，不改变目标或约束。</p>
 </template></section><p v-else-if="error" role="alert">{{ error }}</p></template>
<script setup>
import { noticeText, noticeList } from "@/utils/noticeText.cjs";
import {computed,onBeforeUnmount,onDeactivated,ref,watch} from 'vue';import {verifyRosterAnalysis,verifyRosterContext} from '@/api/rosterPlans';
const props=defineProps({findings:{type:Object,default:null},analysis:{type:Object,default:null},expectedDepartmentId:{type:Number,default:null},references:{type:Object,default:null},active:{type:Boolean,default:true}}),emit=defineEmits(['inspect']),verified=ref(false),error=ref(''),allocationPage=ref(1),optionPage=ref(1),checkPage=ref(1),filter=ref('all');let epoch=0,alive=true;
const source=computed(()=>props.findings?.roster_source),analysis=computed(()=>props.analysis),quantity=value=>value===null||value===undefined?'未知':String(value),objective=value=>!value?'无已证明目标值':`${source.value.objective_mode==='meet_targets_min_penalty'?'服务量不参与排序':`计划服务量 ${quantity(value.planned_slots)}`}；惩罚点 ${quantity(value.penalty_points)}`;
const solveLabels={optimal_proven:'已证明最优（仅限明确声明范围）',feasible_not_proven:'已有可行候选，尚未证明最优',infeasible_proven:'已证明声明约束内不可行',feasibility_unknown:'可行性未知，不能宣称不可行',input_unknown:'资料存在未知项，未证明完整可行性'},checkLabels={satisfied:'已满足',violated:'已知违反',unknown:'未知',not_applicable:'明确不适用',feasible_under_declared_scope:'明确声明范围内可行'},termination={exhausted:'前沿已穷尽',bound_closed:'数学界已闭合',node_limit:'达到节点预算',operation_limit:'达到原语操作预算',frontier_limit:'达到前沿预算',input_unknown:'原资料未知'},kindLabels={personnel_coverage:'人员覆盖',policy:'适用工时政策',qualification:'原资格',availability:'原可用性',accounting:'原时间核算',context_coverage:'全地点值班上下文',presence_overlap:'原在岗重叠',single_duty_presence:'单次在岗时长',minimum_rest:'相邻班次休息',rolling_24h:'连续24小时工时',rolling_7d:'连续7日工时',fixed_minimum_work:'明确固定窗口最少工时',fixed_maximum_work:'明确固定窗口最多工时',minimum_staff:'会话最少人数',maximum_staff:'会话最多人数',required_slots:'硬需求服务量',facility_slot_ceiling:'场景设施净容量',cost:'原惩罚点',capacity:'原场景能力'};
function staffLabel(id){if(id===null)return'';const mapping=props.findings?.roster_plan?.snapshot?.mapping.staff||{},person=Object.keys(mapping).find(key=>mapping[key]===id);return person?`原人员 #${person}`:id;}
function sessionLabel(id){const row=source.value?.sessions.find(row=>row.session_id===id);return row?`${row.business_date} · ${row.start_at} 至 ${row.end_at}`:id;}
function optionLabel(id){const row=source.value.options.find(row=>row.option_id===id);return row?`${staffLabel(row.staff_id)} · ${sessionLabel(row.session_id)}`:id;}
const allocations=computed(()=>analysis.value?.solution?.session_allocations.slice((allocationPage.value-1)*20,allocationPage.value*20)||[]),selectedOptions=computed(()=>analysis.value?.solution?.selected_option_ids.slice((optionPage.value-1)*20,optionPage.value*20)||[]),checks=computed(()=>[...(analysis.value?.solution?.checks||[]),...(analysis.value?.submitted_candidate_check?.checks||[])].filter(row=>filter.value==='all'||row.status===filter.value)),checkRows=computed(()=>checks.value.slice((checkPage.value-1)*20,checkPage.value*20));
watch(filter,()=>checkPage.value=1);watch(()=>[props.findings,props.analysis,props.expectedDepartmentId,props.references,props.active],async()=>{const n=++epoch;verified.value=false;error.value='';allocationPage.value=optionPage.value=checkPage.value=1;if(!alive||!props.active||!props.findings)return;const valid=await verifyRosterContext(props.findings,props.expectedDepartmentId,props.references)&&(!props.analysis||await verifyRosterAnalysis(source.value,props.analysis,props.findings.roster_plan.projection_hash));if(!alive||!props.active||n!==epoch)return;verified.value=valid;if(!valid)error.value='排班原件、完整集合、脱敏投影或固定结果绑定无法一致核对，已拒绝展示。';},{deep:true,immediate:true,flush:'sync'});onDeactivated(()=>{epoch++;verified.value=false;});onBeforeUnmount(()=>{alive=false;epoch++;verified.value=false;});
</script>
<style scoped>p{line-height:1.7}.hash{overflow-wrap:anywhere}.el-table{margin:12px 0}</style>
